[] -> true;_ -> exit({error,{asn1, {unexpected,Tlv5}}}) % extra fields not allowed
end,
Res1 = {'AD-KDCIssued',Term1,Term2,Term3,Term4},
Res1.


%%================================
%%  AD-AND-OR
%%================================
'enc_AD-AND-OR'(Val) ->
    'enc_AD-AND-OR'(Val, [<<48>>]).

'enc_AD-AND-OR'(Val, TagIn) ->
{_,Cindex1,Cindex2} = Val,

%%-------------------------------------------------
%% attribute condition-count(1) with type INTEGER
%%-------------------------------------------------
   {EncBytes1,EncLen1} = encode_integer(Cindex1, [<<2>>,<<160>>]),

%%-------------------------------------------------
%% attribute elements(2)   External KRB5:AuthorizationData
%%-------------------------------------------------
   {EncBytes2,EncLen2} = 'enc_AuthorizationData'(Cindex2, [<<48>>,<<161>>]),

   BytesSoFar = [EncBytes1, EncBytes2],
LenSoFar = EncLen1 + EncLen2,
encode_tags(TagIn, BytesSoFar, LenSoFar).


'dec_AD-AND-OR'(Tlv) ->
   'dec_AD-AND-OR'(Tlv, [16]).

'dec_AD-AND-OR'(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),

%%-------------------------------------------------
%% attribute condition-count(1) with type INTEGER
%%-------------------------------------------------
[V1|Tlv2] = Tlv1, 
Term1 = begin
Val1 = decode_integer(V1, [131072,2]),
if -2147483648 =< Val1, Val1 =< 2147483647 ->
Val1;
true ->
exit({error,{asn1,bad_range}})
end
end,

%%-------------------------------------------------
%% attribute elements(2)   External KRB5:AuthorizationData
%%-------------------------------------------------
[V2|Tlv3] = Tlv2, 
Term2 = 'dec_AuthorizationData'(V2, [131073,16]),

case Tlv3 of
[] -> true;_ -> exit({error,{asn1, {unexpected,Tlv3}}}) % extra fields not allowed
end,
Res1 = {'AD-AND-OR',Term1,Term2},
Res1.


